import openpyxl
p='inputs/delivery.xlsx'
wbf = openpyxl.load_workbook(p, data_only=False)
wbv = openpyxl.load_workbook(p, data_only=True)
for name in wbf.sheetnames:
    wf = wbf[name]; wv = wbv[name]
    print('SHEET', name, wf.max_row, wf.max_column, 'dims', wf.dimensions)
    for r in range(1, min(wf.max_row,13)+1):
        cells=[]
        for c in range(1, min(wf.max_column,3)+1):
            cf = wf.cell(r,c); cv = wv.cell(r,c)
            if cf.data_type == 'f':
                cells.append((cf.coordinate, 'FORMULA=' + str(cf.value), 'cached=' + str(cv.value)))
            else:
                cells.append((cf.coordinate, repr(cf.value)))
        print(' row', r, cells)
print('defined_names', list(getattr(wbf,'defined_names',{}) or {}))

